diff --git a/crates/aqua-gpu-d3d11/tests/conformance.rs b/crates/aqua-gpu-d3d11/tests/conformance.rs
index aa72406..170a0d4 100644
--- a/crates/aqua-gpu-d3d11/tests/conformance.rs
+++ b/crates/aqua-gpu-d3d11/tests/conformance.rs
@@ -99,3 +99,20 @@ fn integrated_unorm_surface_matches_reference() {
     let _software = support::software();
     run(support::integrated(), SurfaceFormat::Bgra8Unorm, EIGHT_BIT);
 }
+
+#[test]
+fn legacy_scaled_mask_matches_reference() {
+    use aqua_core::{geometry::Rect, Oklch};
+    use aqua_gpu_ref::conformance::{cases::{build, glyph_run}, compare, Session};
+    use aqua_graph::Extent;
+    let case = build("legacy_scaled_mask", Extent { width: 96, height: 72 }, Oklch::TRANSPARENT, &[
+        glyph_run(&[(Rect { x: 4.0, y: 8.0, w: 24.0, h: 24.0 }, Rect { x: 16.0, y: 0.0, w: 16.0, h: 16.0 }, "#808080", 0.65)]),
+    ]);
+    let mut reference = RefBackend::new();
+    let mut backend = OffscreenBackend::with_format(AdapterPreference::HighPerformance, SurfaceFormat::Rgba16Float).unwrap();
+    let expected = Session::new(&mut reference).render_case(&case).unwrap();
+    let actual = Session::new(&mut backend).render_case(&case).unwrap();
+    let comparison = compare(&case.plan, &expected, &actual, Tolerance::default());
+    eprintln!("legacy sampling comparison {comparison:?}");
+    assert!(comparison.passed());
+}
